UPDATE queue_message
SET status = 'PENDING', lease_token = NULL, lease_expires_at = NULL, available_at = #{now}, last_error_type = 'LEASE_EXPIRED'
WHERE status = 'PROCESSING' AND lease_expires_at <= #{now}

mapper.delete:
WITH expired AS (
  SELECT id FROM queue_message WHERE status = 'SUCCEEDED' AND succeeded_at < #{cutoff}
  ORDER BY succeeded_at, id LIMIT #{limit}
) DELETE FROM queue_message WHERE id IN (SELECT id FROM expired)
